-- ve-demo-showroom: the Green Leaf Kitchen tour video (V) as a lookbook in Depot > Guides and tours, 2026-11-08 (Sean: "Give me the lookbook...
-- I didn't like the framing of the shots and they're going too fast"). The 60 frames of v-tour-v2 as built (a new still about every 3 s, a slow zoom),
-- each with V's words over it (stt word timings, el-media). Stills in vegan-media/media/tours/green-leaf-tour/. Applied through the connector.
insert into ve_video_tours (slug,title,kind,page_url,narrator,voice_id,script_doc,status) values ('green-leaf-tour','Green Leaf Kitchen tour (BrandDesk demo)','tool','/business/sample/tour','v','Nhs7eitvQWFTQBsf0yiT','docs/proposals/green-leaf-tour-script.md','lookbook') on conflict (slug) do update set status='lookbook';
insert into ve_video_chapters (tour_id,n,title,line,audio_url,audio_ver,stt_ok,seconds) select t.id,c.n,c.title,c.line,'https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/v/green-leaf-tour/tour-'||c.n||(case when c.n=7 then '-v2' else '-v1' end)||'.mp3',case when c.n=7 then 2 else 1 end,true,c.s from ve_video_tours t, (values (1,'Welcome','Hi, I''m V. This is Green Leaf Kitchen. It''s not a real restaurant. It''s our sample, built to show you what a Vegan restaurant''s website can look like when we build it with you. Watch the tour, then tap around. Nothing you do here is saved',15.4645),(2,'The home page','The first screen answers what people want to know. Are you open? What''s good? And how do I order? The favorites row is ranked by what members vote for, so it stays current on its own.',11.7029),(3,'Story and space','People choose a restaurant for the people behind it. Your story plays right on the page, and your space shows by day, at night, inside, and with your team.',9.8743),(4,'Every dish','Every dish has its own page, allergens, a nutrition estimate, and what''s in it with where each ingredient comes from. When it''s a brand in our Directory, it links to that brand''s page.',11.9641),(5,'Members','Members of Vegans Explore can sign in here with the account they already have. They vote for their favorite dishes once a day and save the ones they want to come back for.',10.3967),(6,'The owner','Switch to the owner and the same page becomes yours to update. Change an ingredient, add a brand from our Directory, and the dish page shows it',9.3257),(7,'Ordering','Ordering is short. Add what you want, choose pickup, and pay. When your point of sale is connected, orders go straight to your kitchen. Vegans Explore Delivery is coming soon',12.4865),(8,'Three looks','This is one site in three looks. Same menu, same story, different colors and type. Yours is built from your own brand kit',8.96),(9,'Vegans Explore page','Your site connects to your Vegans Explore page, where members find you, vote for you, and check in when they visit.',7.1053),(10,'Community','Your regulars become your community. Members unlock rewards you choose, like a free drink or a seat at your chef''s table with the points they earn on Vegans Explore. There are only so many, first come, first served, and your club is a Guide on Vegans Explore, so it brings people in and sends them out to the rest of the community',22.1518),(11,'Next step','Want one like this for your restaurant? Tap Talk to our team and a real person will walk you through it',6.3478)) c(n,title,line,s) where t.slug='green-leaf-tour' on conflict (tour_id,n) do update set line=excluded.line, audio_url=excluded.audio_url, seconds=excluded.seconds;
delete from ve_video_shots where tour_id=(select id from ve_video_tours where slug='green-leaf-tour');
insert into ve_video_shots (tour_id,chapter_n,ord,kind,brief,image_url,audio_from,audio_to,status,readiness,line) select t.id,v.ch,v.o,v.kind,v.brief,v.img,v.af,v.at,'proposed','ready',v.line from ve_video_tours t, (values (1,1,'illustration','V in the café with the tablet (her tour picture). Held 1.9 s with a slow zoom, then cut.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/tours/green-leaf-tour/f01-V.jpg',0,1.5,'Hi, I''m V.'),(1,2,'screen','The home page''s first screen: header, Open now, the headline. Held 1.8 s with a slow zoom, then cut.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/tours/green-leaf-tour/f02-hero-top.jpg',1.5,3.3,'This is Green Leaf Kitchen.'),(1,3,'screen','The Sample bar on top of the site (Take the tour, the three looks, ordering). Held 2.7 s with a slow zoom, then cut.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/tours/green-leaf-tour/f03-samplebar.jpg',3.3,6.0,'It''s not a real restaurant. It''s our sample,'),(1,4,'screen','The headline and the line under it. Held 3.3 s with a slow zoom, then cut.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/tours/green-leaf-tour/f04-hero-head.jpg',6.0,9.34,'built to show you what a Vegan restaurant''s website can look like'),(1,5,'screen','The space: the outside by day. Held 1.7 s with a slow zoom, then cut.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/tours/green-leaf-tour/f05-space-out.jpg',9.34,11.06,'when we build it with you.'),(1,6,'screen','The tour page: V, Play the tour and Talk to our team. Held 2.4 s with a slow zoom, then cut.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/tours/green-leaf-tour/f06-tour-talk.jpg',11.06,13.5,'Watch the tour, then tap around.'),(1,7,'screen','The menu page, top. Held 2.4 s with a slow zoom, then cut.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/tours/green-leaf-tour/f07-menu-top.jpg',13.5,15.4645,'Nothing you do here is saved'),(2,1,'screen','The today strip: hours, address, phone, 100% Vegan. Held 2.9 s with a slow zoom, then cut.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/tours/green-leaf-tour/f08-today.jpg',0,2.94,'The first screen answers what people want to know.'),(2,2,'screen','The home page''s first screen: header, Open now, the headline. Held 1.6 s with a slow zoom, then cut.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/tours/green-leaf-tour/f09-hero-top.jpg',2.94,4.49,'Are you open? What''s good?'),(2,3,'screen','The hero''s See the menu and Order buttons. Held 1.9 s with a slow zoom, then cut.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/tours/green-leaf-tour/f10-hero-btns.jpg',4.49,6.36,'And how do I order?'),(2,4,'screen','Favorites: What people come back for. Held 1.8 s with a slow zoom, then cut.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/tours/green-leaf-tour/f11-fav-head.jpg',6.36,8.18,'The favorites row is ranked by'),(2,5,'screen','A favorite card with the heart vote pressed (as a member). Held 1.6 s with a slow zoom, then cut.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/tours/green-leaf-tour/f12-m-vote.jpg',8.18,9.74,'what members vote for,'),(2,6,'screen','The favorites rail, a third card. Held 2.4 s with a slow zoom, then cut.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/tours/green-leaf-tour/f13-fav-card3.jpg',9.74,11.7029,'so it stays current on its own.'),(3,1,'screen','Our story section. Held 3.3 s with a slow zoom, then cut.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/tours/green-leaf-tour/f14-story.jpg',0,3.31,'People choose a re